package cn.zhuatech.sbom.controller; import cn.zhuatech.sbom.common.ApiResponse; import cn.zhuatech.sbom.dto.SbomDto.*; import cn.zhuatech.sbom.service.SbomService; import cn.zhuatech.sbom.service.ComponentRiskService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final SbomService service;private final ComponentRiskService componentRisk;public WorkspaceController(SbomService service,ComponentRiskService componentRisk){this.service=service;this.componentRisk=componentRisk;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("组件处置反馈已提交",service.report(id,request));}@PostMapping("/component-risk") public ApiResponse<ComponentRiskService.Result> evaluate(@Valid @RequestBody ComponentRiskService.Request request){return ApiResponse.ok("组件风险评估完成",componentRisk.evaluate(request));}}
